#!/usr/bin/env python3
"""Generates scenes/weekend_cover.scene, the final scene of "Ray Tracing in
One Weekend": a ground plane of small random spheres around three big ones.

The book picks the small spheres at random each run; this script uses a fixed
seed so the scene file (and its render) is reproducible.

Usage: python3 tools/gen_weekend_cover.py > scenes/weekend_cover.scene
"""
import math
import random

random.seed(1)

print("""# "Ray Tracing in One Weekend" final cover scene.
# Generated by tools/gen_weekend_cover.py; edit that script, not this file.

image_width  1200
aspect_ratio 16/9
samples_per_pixel 10
max_depth    50

camera lookfrom 13 2 3  lookat 0 0 0  vup 0 1 0  vfov 20
aperture 0.6
focus    10

material ground lambertian 0.5 0.5 0.5
material glass  dielectric 1.5
material big_matte lambertian 0.4 0.2 0.1
material big_metal metal 0.7 0.6 0.5 0.0

sphere 0 -1000 0  1000  ground
""")

for a in range(-11, 11):
    for b in range(-11, 11):
        choose_mat = random.random()
        cx, cy, cz = a + 0.9 * random.random(), 0.2, b + 0.9 * random.random()
        if math.dist((cx, cy, cz), (4, 0.2, 0)) <= 0.9:
            continue
        name = f"m_{a + 11}_{b + 11}"
        if choose_mat < 0.8:
            r, g, bl = (random.random() * random.random() for _ in range(3))
            print(f"material {name} lambertian {r:.4f} {g:.4f} {bl:.4f}")
        elif choose_mat < 0.95:
            r, g, bl = (random.uniform(0.5, 1) for _ in range(3))
            fuzz = random.uniform(0, 0.5)
            print(f"material {name} metal {r:.4f} {g:.4f} {bl:.4f} {fuzz:.4f}")
        else:
            name = "glass"
        print(f"sphere {cx:.4f} {cy} {cz:.4f}  0.2  {name}")

print("""
sphere  0 1 0  1.0  glass
sphere -4 1 0  1.0  big_matte
sphere  4 1 0  1.0  big_metal""")
